-- Heroes of Horror: taint subsystem.
-- Source: Heroes of Horror, Chapter 4, pp. 62-68. Mechanical text is summarized; source pages remain authoritative.

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,summary,tags,mechanics) AS (VALUES
('hoh-taint-thresholds','Taint Thresholds','62-63','taint','table',1,0,
 'Corruption is measured against Constitution and depravity against Wisdom; Table 4-1 determines no, mild, moderate, severe, and terminal taint bands.',
 '["taint","corruption","depravity","thresholds"]',
 '{"corruption_ability":"constitution","depravity_ability":"wisdom","rows":[{"ability_min":1,"ability_max":4,"none":[0,0],"mild":[1,1],"moderate":[2,5],"severe":[6,13],"terminal_min":14},{"ability_min":5,"ability_max":8,"none":[0,0],"mild":[1,3],"moderate":[4,11],"severe":[12,27],"terminal_min":28},{"ability_min":9,"ability_max":12,"none":[0,0],"mild":[1,5],"moderate":[6,17],"severe":[18,41],"terminal_min":42},{"ability_min":13,"ability_max":16,"none":[0,0],"mild":[1,7],"moderate":[8,23],"severe":[24,55],"terminal_min":56},{"ability_min":17,"ability_max":20,"none":[0,0],"mild":[1,9],"moderate":[10,29],"severe":[30,69],"terminal_min":70},{"ability_min":21,"ability_max":24,"none":[0,0],"mild":[1,11],"moderate":[12,35],"severe":[36,83],"terminal_min":84},{"ability_min":25,"ability_max":28,"none":[0,0],"mild":[1,13],"moderate":[14,41],"severe":[42,97],"terminal_min":98},{"ability_min":29,"ability_max":32,"none":[0,0],"mild":[1,15],"moderate":[16,47],"severe":[48,111],"terminal_min":112},{"ability_min":33,"ability_max":36,"none":[0,0],"mild":[1,17],"moderate":[18,53],"severe":[54,125],"terminal_min":126}]}'),
('hoh-taint-progression','Taint Progression and Locked Symptoms','63','taint','subsystem',1,0,
 'Crossing taint thresholds adds persistent symptoms. Prompt treatment within 24 hours can reverse a newly crossed threshold; otherwise stronger magic is required.',
 '["taint","symptoms","progression"]',
 '{"mild":{"symptoms_added":1,"treatment_window_hours":24,"window_spells":["restoration","heal","greater restoration"],"required_result":"reduce score to no-taint band","after_window":"miracle or wish required to remove the locked mild symptom and return to no taint"},"moderate":{"symptoms_added":1,"keeps_lower_symptoms":true,"treatment_window_hours":24,"window_spells":["heal","greater restoration"],"required_result":"reduce score to mild band","after_window":"miracle or wish required to remove the locked moderate symptom and return to mild"},"severe":{"symptoms_added":1,"keeps_lower_symptoms":true,"treatment_window_hours":24,"window_spells":["greater restoration"],"required_result":"reduce score to moderate band","after_window":"miracle or wish required to remove the locked severe symptom and return to moderate"},"terminal_corruption":{"result":"death","delay_to_transformation":"1d6 hours","transformation":"tainted minion","control":"DM"},"terminal_depravity":{"result":"irretrievable madness","transformation":"tainted raver","control":"DM"},"symptom_selection":{"first":"roll 1d10","advancement":"when a higher taint band is reached, add the symptom immediately to the right in the same table row"}}'),
('hoh-corruption-symptoms','Corruption Symptoms','63-65','taint','table',1,0,
 'Table 4-2 maps each d10 row to linked mild, moderate, and severe physical corruption symptoms and their mechanical effects.',
 '["taint","corruption","physical-symptoms"]',
 '{"rows":[{"d10":1,"mild":{"name":"Dead Eye","effects":{"concealment_miss_chance_rolls":2,"miss_if_either_misses":true}},"moderate":{"name":"Lips Shrink","effects":{"charisma_ability_and_skill_penalty":-2}},"severe":{"name":"Lich Eyes","effects":{"darkvision_ft":60,"existing_darkvision_bonus_ft":30,"bright_light_initial":"blinded 1 round","bright_light_later":"dazzled while exposed"}}},{"d10":2,"mild":{"name":"Ear Scabs","effects":{"listen_penalty":-2}},"moderate":{"name":"Fingers and Toes Fuse","effects":{"attack_penalty":-2,"somatic_spell_caster_level_check_dc":20,"failure":"spell fails"}},"severe":{"name":"Shriveled Flesh","effects":{"immediate_hp_loss":"Hit Dice","hp_gained_per_level_penalty":-1,"minimum_hp_gain_per_level":0}}},{"d10":3,"mild":{"name":"Gums Swell","effects":{"verbal_spell_caster_level_check_dc":20,"failure":"spell fails"}},"moderate":{"name":"Bones Thicken","effects":{"strength_change":2,"dexterity_change":-4}},"severe":{"name":"Great Swollen Growths","effects":{"armor_class_penalty":-2}}},{"d10":4,"mild":{"name":"Feet Curl","effects":{"speed_penalty_ft":-10}},"moderate":{"name":"Joint Pain","effects":{"reflex_save_penalty":-3}},"severe":{"name":"Spine Twists","effects":{"dexterity_change":-2}}},{"d10":5,"mild":{"name":"Lumps","effects":{"trigger":"run or charge","fortitude_dc":20,"failure":"fatigued"}},"moderate":{"name":"Eruption of Sores","effects":{"strength_based_ability_and_skill_penalty":-1,"charisma_based_ability_and_skill_penalty":-1}},"severe":{"name":"Wrigglers","effects":{"strength_change":-2,"intimidate_bonus":2,"other_charisma_check_penalty":-4}}},{"d10":6,"mild":{"name":"Odor of Decay","effects":{"handle_animal_penalty":-2,"ride_penalty":-2,"wild_empathy_penalty":-2}},"moderate":{"name":"Paralyzed Face","effects":{"bluff_bonus":1,"other_charisma_ability_and_skill_penalty":-1}},"severe":{"name":"Nose Rots","effects":{"charisma_change":-2}}},{"d10":7,"mild":{"name":"Palsy","effects":{"ranged_attack_penalty":-2}},"moderate":{"name":"Uncontrollable Seizures","effects":{"initiative_penalty":-4}},"severe":{"name":"Skull Deformed","effects":{"intelligence_change":-2,"wisdom_change":-2,"will_save_penalty":-3}}},{"d10":8,"mild":{"name":"Skin Seeps","effects":{"escape_artist_bonus":2,"grapple_resist_escape_pin_bonus":2,"climb_penalty":-2,"sleight_of_hand_penalty":-2,"opponent_disarm_attack_bonus":2}},"moderate":{"name":"Blood Eruption","effects":{"trigger":"beginning of combat","fortitude_dc":15,"failure":"sickened 4 rounds"}},"severe":{"name":"Internal Corruption","effects":{"constitution_change":-2,"externally_visible":false,"can_replace_other_symptom_for_some_prestige_classes":true,"bonus_feat_if_replacing_mild":false}}},{"d10":9,"mild":{"name":"Skin Sloughs","effects":{"diplomacy_penalty":-2,"gather_information_penalty":-2,"perform_penalty":-2}},"moderate":{"name":"Skin Thickens","effects":{"natural_armor_bonus":1,"dexterity_based_ability_and_skill_penalty":-2}},"severe":{"name":"Skin Lichen","effects":{"strength_dexterity_constitution_based_ability_and_skill_penalty":-2}}},{"d10":10,"mild":{"name":"Winded","effects":{"combat_round_3_and_later":"staggered"}},"moderate":{"name":"Chronic Illness","effects":{"fortitude_save_penalty":-3}},"severe":{"name":"Lungs Eaten Away","effects":{"strength_change":-1,"dexterity_change":-1,"constitution_change":-1}}}]}'),
('hoh-depravity-symptoms','Depravity Symptoms','65-66','taint','table',1,0,
 'Table 4-3 maps each d10 row to linked mild, moderate, and severe mental depravity symptoms and their mechanical effects.',
 '["taint","depravity","mental-symptoms"]',
 '{"rows":[{"d10":1,"mild":{"name":"Aggressive","effects":{"armor_class_penalty":-1}},"moderate":{"name":"Treacherous","effects":{"trigger":"attack of opportunity becomes available against ally or enemy","will_dc":20,"failure":"must make attack of opportunity","multiple_targets":"choose randomly"}},"severe":{"name":"Murderous","effects":{"trigger":"coup de grace opportunity exists","result":"must deliver coup de grace","allies_and_enemies_indistinguishable_for_trigger":true}}},{"d10":2,"mild":{"name":"Bestial","effects":{"handle_animal_bonus":2,"ride_bonus":2,"wild_empathy_bonus":2,"other_charisma_ability_and_skill_penalty":-1}},"moderate":{"name":"Deranged","effects":{"intelligence_based_ability_and_skill_penalty":-2}},"severe":{"name":"Unbalanced","effects":{"combat_turns_confused":"first turn and every other turn thereafter"}}},{"d10":3,"mild":{"name":"Compulsive","effects":{"daily_fortitude_dc":10,"failure_nonlethal_damage":"1d4","ritual":"player selects a compulsive ritual"}},"moderate":{"name":"Hysterical","effects":{"combat_round_2":"may take only one move action or one standard action"}},"severe":{"name":"Unresponsive","effects":{"wisdom_change":-2}}},{"d10":4,"mild":{"name":"Crazed","effects":{"trigger":"surprised at encounter start","first_action":"equal chance charge foe or run away"}},"moderate":{"name":"Jittery","effects":{"trigger":"hit while flat-footed","result":"panicked"}},"severe":{"name":"Craven","effects":{"casting":"must always cast defensively","attacking":"must always fight defensively"}}},{"d10":5,"mild":{"name":"Disoriented","effects":{"trigger":"surprised at encounter start","result":"dazed 1 round"}},"moderate":{"name":"Hallucinating","effects":{"initiative_penalty":-6}},"severe":{"name":"Paranoid","effects":{"trigger":"ally in combat makes an attack and misses","penalty_to_rolls_that_turn":-1,"cumulative_per_missing_ally":true}}},{"d10":6,"mild":{"name":"Mildly Phobic","effects":{"will_dc":"12 + challenge CR","cr_below_1_counts_as":0,"failure":"shaken"}},"moderate":{"name":"Moderately Phobic","effects":{"replaces":"Mildly Phobic","will_dc":"14 + challenge CR","failure":"frightened"}},"severe":{"name":"Severely Phobic","effects":{"replaces":"Moderately Phobic","will_dc":"16 + challenge CR","failure":"panicked"}}},{"d10":7,"mild":{"name":"Neglectful","effects":{"charisma_based_ability_and_skill_penalty":-2}},"moderate":{"name":"Distracted","effects":{"skill_check_penalty":-2}},"severe":{"name":"Enthralled","effects":{"against_evil_attack_penalty":-4,"damage_against_evil":"nonlethal only"}}},{"d10":8,"mild":{"name":"Opinionated","effects":{"combat_round_1":"always flat-footed"}},"moderate":{"name":"Solipsistic","effects":{"trigger":"struck in combat","will_dc":20,"failure_extra_damage":"1 per die of damage received"}},"severe":{"name":"Hubristic","effects":{"divine_healing":"no effect"}}},{"d10":9,"mild":{"name":"Prophetic","effects":{"prophecy_frequency":"one different prophecy per week","accurate_chance_percent":10,"nightmares":"suffers usual effects of continual nightmares"}},"moderate":{"name":"Delusional","effects":{"wisdom_based_ability_and_skill_penalty":-2}},"severe":{"name":"Apathetic","effects":{"charisma_change":-2,"wisdom_change":-2}}},{"d10":10,"mild":{"name":"Sycophantic","effects":{"listen_penalty":-2,"spot_penalty":-2,"enemy_listen_bonus_to_hear_character":2}},"moderate":{"name":"Weak-Willed","effects":{"will_save_penalty":-3}},"severe":{"name":"Fatalistic","effects":{"saving_throw_penalty":-3}}}]}'),
('hoh-taint-bonus-feats','Taint and Bonus Feats','67','taint','rule',1,0,
 'A character gains a bonus feat on first reaching moderate taint and another on first reaching severe taint; taint-prerequisite feats become inactive if the required taint level is later lost.',
 '["taint","feats"]',
 '{"bonus_feat_at":["moderate","severe"],"feat_choice":"any feat whose prerequisites are met","taint_prerequisite_feat_below_requirement":"inoperative, not removed","reactivates_if_requirement_returns":true}'),
('hoh-taint-absorbing-items','Taint-Absorbing Items','67','taint','table',1,0,
 'Natural protective items absorb incoming taint but decay as they do so; carrying more items increases protection only through four items and then becomes counterproductive.',
 '["taint","items","resistance"]',
 '{"cost_gp_each":100,"single_item_capacity":7,"capacities_by_item_count":{"1":7,"2":12,"3":15,"4":16,"5":15,"6":12,"7":1},"multiple_items":"absorbed taint is distributed among all carried items and they decompose together","incoming_taint_absorbed_until_capacity":true}'),
('hoh-taint-and-alignment','Taint and Alignment','67','taint','rule',1,0,
 'Moderate or worse taint carries an evil aura and can interfere with divine class obligations; actual alignment changes remain a DM judgment.',
 '["taint","alignment","cleric","paladin"]',
 '{"detect_evil":{"minimum_taint":"moderate","registers_as_evil":true},"alignment_guidance":{"moderate":"neutral at best","severe":"usually evil","actual_change":"DM discretion"},"good_cleric":{"trigger":"severe taint","loses":["spells","class features"],"restoration_requirement":"atonement and taint reduced to at most moderate","eberron_exception":true},"paladin":{"trigger":"moderate taint","loses":["paladin spells","paladin abilities","further paladin advancement"],"restoration_requirement":"atonement and taint reduced to at most mild"}}'),
('hoh-cleansing-taint','Cleansing Taint','67-68','taint','procedure',1,0,
 'Taint can be reduced only for a willing subject, and spell cleansing must occur outside tainted areas. Specific spells, good deeds, and sacred springs reduce corruption or depravity under defined limits.',
 '["taint","cleansing","atonement","restoration"]',
 '{"subject_must_want_cleansing":true,"spell_location":"outside tainted areas","same_spell_per_target_per_day_max":1,"different_spells_same_day_allowed":true,"threshold_lock":{"after_24_hours":"ordinary cleansing cannot reduce below the newly crossed taint band","exceptions":["atonement","miracle","wish"]},"spells":{"atonement":{"quest_required":true,"caster_xp_cost":500,"reduction_each_score":"chosen amount up to caster level","can_cross_locked_threshold":true},"heal":{"reduction_each_score":"1 per 3 caster levels","can_cross_if_within_hours":24,"eligible_crossings":["mild","moderate"]},"miracle":{"result":"place target at highest value of next lower taint category","ignores_elapsed_time":true},"wish":{"result":"place target at highest value of next lower taint category","ignores_elapsed_time":true},"remove_curse":{"depravity_reduction":1},"remove_disease":{"corruption_reduction":1},"restoration":{"reduction_each_score":"1 per 4 caster levels","can_cross_if_within_hours":24,"eligible_crossings":["mild"]},"greater_restoration":{"reduction_each_score":"caster level","can_cross_if_within_hours":24,"eligible_crossings":["any newly crossed threshold"]}},"good_deeds":{"requires_deity_cleric_ritual":true,"adventuring_during_ritual_deed":"restart unless using quest alternative","daily_repetition_days":7,"depravity_reduction_per_week":1,"quest_alternative":"depravity -1 per week required to complete quest"},"sacred_spring":{"corruption_reduction_per_day":1,"allowed_activities":["resting","eating","sleeping","meditation","normal conversation"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'hoh-rule-'||d.slug,'hoh-3.5',d.source_page,d.slug,d.name,d.summary,d.summary,0,NULL,1,
       d.category,d.kind,d.is_variant,d.default_enabled,NULL,NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_rules r WHERE r.slug=d.slug AND r.owner_user_id IS NULL);
